{"content":"package api

import (
	"encoding/json"
	"io"
	"net/http"
	"strconv"
	"strings"
)

// errorResponse is the JSON shape for error responses.
type errorResponse struct {
	Error string `json:"error"`
}

// handler wires the HTTP endpoints to a Store.
type handler struct {
	store *Store
}

// NewHandler returns an http.Handler serving the notes API backed by s.
func NewHandler(s *Store) http.Handler {
	h := &handler{store: s}
	mux := http.NewServeMux()
	mux.HandleFunc("/healthz", h.handleHealthz)
	mux.HandleFunc("/notes", h.handleNotes)
	mux.HandleFunc("/notes/{id}", h.handleNote)
	return mux
}

// handleHealthz reports liveness.
func (h *handler) handleHealthz(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeError(w, http.StatusMethodNotAllowed, "method not allowed")
		return
	}
	w.Header().Set("Content-Type", "text/plain")
	w.WriteHeader(http.StatusOK)
	io.WriteString(w, "ok")
}

// handleNotes handles GET (list) and POST (create) on /notes.
func (h *handler) handleNotes(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		h.listNotes(w, r)
	case http.MethodPost:
		h.createNote(w, r)
	default:
		writeError(w, http.StatusMethodNotAllowed, "method not allowed")
	}
}

// listNotes writes all notes, optionally filtered by ?q= (case-insensitive
// substring match on title or body), as a JSON array ordered by id.
func (h *handler) listNotes(w http.ResponseWriter, r *http.Request) {
	notes := h.store.List()
	if q := strings.ToLower(r.URL.Query().Get("q")); q != "" {
		filtered := make([]Note, 0)
		for _, n := range notes {
			if strings.Contains(strings.ToLower(n.Title), q) || strings.Contains(strings.ToLower(n.Body), q) {
				filtered = append(filtered, n)
			}
		}
		notes = filtered
	}
	writeJSON(w, http.StatusOK, notes)
}

// createNote decodes the JSON body and stores a new note.
func (h *handler) createNote(w http.ResponseWriter, r *http.Request) {
	var n Note
	if err := json.NewDecoder(r.Body).Decode(&n); err != nil {
		writeError(w, http.StatusBadRequest, "invalid JSON body")
		return
	}
	if strings.TrimSpace(n.Title) == "" {
		writeError(w, http.StatusBadRequest, "title is required")
		return
	}
	writeJSON(w, http.StatusCreated, h.store.Create(n.Title, n.Body))
}

// handleNote handles GET and DELETE on /notes/{id}.
func (h *handler) handleNote(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet, http.MethodDelete:
	default:
		writeError(w, http.StatusMethodNotAllowed, "method not allowed")
		return
	}
	id, err := strconv.Atoi(r.PathValue("id"))
	if err != nil {
		writeError(w, http.StatusBadRequest, "id must be an integer")
		return
	}
	switch r.Method {
	case http.MethodGet:
		n, ok := h.store.Get(id)
		if !ok {
			writeError(w, http.StatusNotFound, "note not found")
			return
		}
		writeJSON(w, http.StatusOK, n)
	case http.MethodDelete:
		if !h.store.Delete(id) {
			writeError(w, http.StatusNotFound, "note not found")
			return
		}
		w.WriteHeader(http.StatusNoContent)
	}
}

// writeJSON writes v as a JSON response with the given status.
func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(v)
}

// writeError writes a JSON error response with the given status.
func writeError(w http.ResponseWriter, status int, msg string) {
	writeJSON(w, status, errorResponse{Error: msg})
}
